// Normalize one HN comment into the common gig schema
const hit = $json;
// Decode common entities; &amp; goes last to avoid double-decoding
const decode = s => s
  .replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/&#x2F;/g, '/').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&amp;/g, '&');
// Tags first, then entities (so escaped text isn't mistaken for markup)
const text = decode((hit.comment_text || '')
  .replace(/<p>/g, '\n').replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').trim();

return {
  json: {
    title: text.split('\n')[0].trim().slice(0, 120), // HN posts lead with a headline line
    url: `https://news.ycombinator.com/item?id=${hit.objectID}`,
    source: 'hn-freelancer',
    posted_at: hit.created_at,
    description: text,
    budget_text: '',
    external_id: hit.objectID,
    meta: { author: hit.author, story_id: hit.story_id }
  }
};

// Normalize one Remotive job into the common gig schema
const j = $json;
const decode = s => s
  .replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&amp;/g, '&'); // &amp; last to avoid double-decoding
// Strip tags first (keeping line breaks), then decode entities
const text = decode((j.description || '')
  .replace(/<(br|\/p|\/li|\/h\d)[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();

return { json: {
  title: decode(j.title || ''),
  url: j.url,
  source: 'remotive',
  posted_at: j.publication_date + 'Z',
  description: text,
  budget_text: j.salary || '',
  external_id: String(j.id),
  meta: { company: j.company_name, job_type: j.job_type, location: j.candidate_required_location }
}};

// Cheap keyword gate before any LLM call. Config-driven; no keywords hardcoded.
const cfg = $('Config').first().json.filters;
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Whole-term, case-insensitive match; an empty list matches nothing
const toRe = list => list.length
  ? new RegExp(list.map(k => `(?<![a-z0-9])${esc(k)}(?![a-z0-9])`).join('|'), 'i')
  : /(?!)/;
const include = toRe(cfg.include_keywords);
const excludeTitle = toRe(cfg.exclude_title_patterns);

return $input.all()
  .map(i => i.json)
  .filter(g => !excludeTitle.test(g.title))            // drop supply-side posts
  .filter(g => cfg.include_bypass_sources.includes(g.source)
            || include.test(`${g.title} ${g.description}`))
  .map(g => ({ json: { ...g, keyword_in_title: include.test(g.title) } }));

// Always runs: the HTTP node outputs 1 item even when hits is empty
const cfg = $('Config').first().json.hn;
const hits = $input.first().json.hits || [];
const threads = hits
  .filter(h => (h.title || '').startsWith(cfg.thread_title_prefix))
  .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()) // newest first
  .slice(0, 2);
if (!threads.length) throw new Error('HN: no freelancer thread matched the title prefix');
const ageDays = (Date.now() - new Date(threads[0].created_at).getTime()) / 86400000;
if (ageDays > cfg.max_thread_age_days) throw new Error(`HN: newest thread is ${Math.round(ageDays)} days old`);
return threads.map(t => ({ json: t }));

// HTTP replaced the gig with the topic JSON, so re-attach the original gig via paired item
const gig = $('Forum: Needs Body Fetch?').item.json;
const cooked = $json.post_stream?.posts?.[0]?.cooked || ''; // VERIFY this path in the real response
const decode = s => s
  .replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const text = decode(cooked
  .replace(/<(br|\/p|\/li|\/h\d)[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
return { json: { ...gig, description: text } };

// Build the per-item user prompt. Cap length: cost, and less room for injected text.
const g = $json;
// const max = $('Config').first().json.llm.max_description_chars;
// Strip any <posting> tags the poster typed, so they can't break out of our delimiters
const full = (g.description || '').replace(/<\/?posting>/gi, '');
const llm_prompt = [
  `Source: ${g.source}`,
  `Title: ${g.title}`,
  `Stated budget (from source metadata): ${g.budget_text || 'none'}`,
  g.meta?.job_type ? `Listing type (from source): ${g.meta.job_type}` : '',
  '<posting>',
  full,
  '</posting>'
].join('\n');
return { json: { ...g, llm_prompt } };

// Re-attach the gig via paired item, then validate the model's output ourselves.
const gig = $('Gigs: Build LLM Prompt').item.json;
const { llm_prompt, ...rest } = gig;
const out = $json.output || {};
const ENUMS = {
  poster_type: ['hirer','worker_seeking_work','partnership_or_promo','other'],
  engagement: ['one_off_project','ongoing_contract','full_time_employment','unknown'],
  n8n_relevance: ['core','secondary','mention_only','none'],
  budget_period: ['per_project','hourly','monthly','yearly','unknown']
};
const LISTS = {
  urgency_signals: ['asap','deadline_given','immediate_start','urgent_wording'],
  red_flags: ['upfront_fee','off_platform_payment','vague_scope','unpaid_trial_work','equity_or_exposure_only']
};
const errors = [];
for (const [k, allowed] of Object.entries(ENUMS))
  if (!allowed.includes(out[k])) errors.push(`${k}: ${JSON.stringify(out[k])}`);
for (const [k, allowed] of Object.entries(LISTS))
  if (!Array.isArray(out[k]) || !out[k].every(v => allowed.includes(v))) errors.push(`${k}: invalid`);
for (const k of ['budget_min', 'budget_max'])
  if (out[k] !== null && typeof out[k] !== 'number') errors.push(`${k}: not number or null`);
if (typeof out.summary !== 'string' || !out.summary.trim()) errors.push('summary: missing');

return { json: { ...rest, extraction: out, extraction_valid: errors.length === 0, extraction_errors: errors } };

// Deterministic scoring. Every weight, table and threshold comes from Config.scoring.
const cfg = $('Config').first().json.scoring;
if (cfg.budget_stated_floor < cfg.budget_unknown_score) throw new Error('Config: budget_stated_floor must be >= budget_unknown_score');
const g = $json;
const x = g.extraction;
const clamp01 = n => Math.max(0, Math.min(1, n));
const pick = (table, key, fallback = 0) => (key in table ? table[key] : fallback);

// Budget: convert to a comparable USD figure; unknown or implausible -> neutral score
let budgetScore = cfg.budget_unknown_score, budgetNote = 'unknown', implausible = false;
const fx = cfg.fx_to_usd[x.currency];
const amounts = [x.budget_min, x.budget_max].filter(n => typeof n === 'number');
if (amounts.length && fx && x.budget_period !== 'unknown') {
  const mid = amounts.reduce((a, b) => a + b, 0) / amounts.length;
  const comparable = mid * fx * pick(cfg.period_factor, x.budget_period, 1);
  if (comparable > cfg.max_plausible_budget_usd) { implausible = true; budgetNote = `implausible (${Math.round(comparable)})`; }
  else { budgetScore = cfg.budget_stated_floor + (1 - cfg.budget_stated_floor) * clamp01(comparable / cfg.budget_cap_usd); budgetNote = `${Math.round(comparable)} USD`; }
}

const ageH = (Date.now() - new Date(g.posted_at).getTime()) / 3600000;
const parts = {
  relevance: clamp01(pick(cfg.relevance_values, x.n8n_relevance) + (g.keyword_in_title ? cfg.title_keyword_bonus : 0)),
  budget: budgetScore,
  recency: Number.isFinite(ageH) ? clamp01(1 - ageH / cfg.recency_decay_hours) : 0,
  urgency: clamp01(x.urgency_signals.reduce((s, k) => s + pick(cfg.urgency_values, k), 0)),
  source_trust: pick(cfg.source_trust, g.source, cfg.source_trust_default),
  engagement: pick(cfg.engagement_values, x.engagement)
};

// Weighted average scaled to 0-100; dividing by the weight sum keeps weights free-form
const wSum = Object.values(cfg.weights).reduce((a, b) => a + b, 0) || 1;
const base = 100 * Object.entries(parts).reduce((s, [k, v]) => s + v * (cfg.weights[k] || 0), 0) / wSum;

// Penalties
let penalty = x.red_flags.reduce((s, f) => s + pick(cfg.red_flag_penalties, f), 0);
const text = `${g.title} ${g.description}`;
const injection_suspected = cfg.injection_patterns.some(p => new RegExp(p, 'i').test(text));
if (injection_suspected) penalty += cfg.injection_penalty;
if (implausible) penalty += cfg.implausible_budget_penalty;

const blocked = x.red_flags.filter(f => cfg.red_flag_block.includes(f));

// Gate: only allowed poster types can score at all
const allowed = cfg.allowed_poster_types.includes(x.poster_type);
const score = (allowed && !blocked.length) ? Math.round(Math.max(0, Math.min(100, base - penalty))) : 0;

return { json: { ...g, score, passes: score >= cfg.min_score,
  score_breakdown: { parts, base: Math.round(base), penalty, budget_note: budgetNote, poster_allowed: allowed },
  injection_suspected, implausible_budget: implausible, blocked_flags: blocked } };

// Label every gig's outcome and sort best-first so the highest scores alert first
const gigs = $input.all().map(i => i.json);
return gigs
  .map(g => {
    let outcome;
    if (g.blocked_flags.length) outcome = 'blocked_red_flag';
    else if (!g.score_breakdown.poster_allowed) outcome = 'filtered_poster_type';
    else if (!g.passes) outcome = 'below_threshold';
    else outcome = 'pending_alert'; // becomes 'alerted' only after delivery (7b)
    return { json: { ...g, outcome, to_alert: outcome === 'pending_alert' } };
  })
  .sort((a, b) => b.json.score - a.json.score);

// Channel-neutral alert fields: plain UNESCAPED strings. Each channel formatter escapes for itself.
const g = $json, x = g.extraction;
const money = n => Number(n).toLocaleString('en-US');

let budget = 'not stated';
if (g.implausible_budget) budget = 'unverified (implausible figure)'; // never present a suspect number as fact
else if (typeof x.budget_min === 'number' || typeof x.budget_max === 'number') {
  const lo = x.budget_min, hi = x.budget_max;
  const range = (lo != null && hi != null && lo !== hi) ? `${money(lo)}–${money(hi)}` : money(lo ?? hi);
  budget = `${range} ${x.currency || ''} (${String(x.budget_period).replace('_', ' ')})`.trim();
} else if (g.budget_text) budget = g.budget_text;

const warnings = [];
if (x.red_flags.length) warnings.push(`Flags: ${x.red_flags.join(', ')}`);
if (g.injection_suspected) warnings.push('Contains instructions aimed at AI readers (screening text or prompt injection)');

return { json: { ...g, alert_fields: {
  title: g.title, score: g.score, source: g.source, budget,
  summary: x.summary, warnings, url: g.url,
  link_label: g.source === 'remotive' ? 'Open posting (via Remotive)' : 'Open posting'
}}};

// Telegram HTML formatting. Escape every untrusted value for this channel.
const a = $json.alert_fields;
const NL = String.fromCharCode(10);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const href = String(a.url).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
const sections = [
  [`<b>${esc(a.title)}</b>`],
  [`Score: <b>${a.score}</b>/100`, `Source: ${esc(a.source)}`, `Budget: ${esc(a.budget)}`],
  [esc(a.summary)],
  ...(a.warnings.length ? [a.warnings.map(w => `⚠️ ${esc(w)}`)] : []),
  [`<a href="${href}">${esc(a.link_label)}</a>`]
];
return { json: { ...$json, alert: { text: sections.map(s => s.join(NL)).join(NL + NL) } } };

// Slack mrkdwn formatting. Slack requires & < > to be escaped in text.
const a = $json.alert_fields;
const NL = String.fromCharCode(10);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Links use <url|label>; a ">" or "|" inside the URL would break the syntax, so encode them
const url = String(a.url).replace(/&/g, '&amp;').replace(/</g, '%3C').replace(/>/g, '%3E').replace(/\|/g, '%7C');
const sections = [
  [`*${esc(a.title)}*`],
  [`Score: *${a.score}*/100`, `Source: ${esc(a.source)}`, `Budget: ${esc(a.budget)}`],
  [esc(a.summary)],
  ...(a.warnings.length ? [a.warnings.map(w => `:warning: ${esc(w)}`)] : []),
  [`<${url}|${esc(a.link_label)}>`]
];
return { json: { ...$json, alert: { text: sections.map(s => s.join(NL)).join(NL + NL) } } };

const NL = String.fromCharCode(10);
const clean = (s, n) => String(s).slice(0, n).replace(/@/g, '@' + String.fromCharCode(8203));
const groups = {};
for (const item of $input.all()) {
  const j = item.json;
  const e = j.error;
  const reason = typeof e === 'string' ? e
    : (e && (e.message || e.description))
    || (Array.isArray(j.extraction_errors) ? j.extraction_errors.join('; ') : 'unknown error');
  const key = j.problem || 'Unspecified problem';
  if (!groups[key]) groups[key] = [];
  groups[key].push({ title: j.title, reason });
}
return Object.entries(groups).map(([problem, list]) => {
  const rows = list.slice(0, 5).map(x => `• ${x.title ? clean(x.title, 80) + ' — ' : ''}${clean(x.reason, 200)}`);
  if (list.length > 5) rows.push(`…and ${list.length - 5} more`);
  const content = [`⚠️ Gig Finder: **${problem}** (${list.length})`, ...rows].join(NL).slice(0, 1900); // Discord's limit is 2000
  return { json: { content } };
});

// An empty category would pass silently, so fail loudly instead
const topics = $input.first().json.topic_list?.topics;
if (!Array.isArray(topics) || topics.length === 0)
  throw new Error('Forum: response contained no topics (endpoint or JSON shape may have changed)');
return $input.all();

// Error items carry only an error message. Try to recover the gig's title via paired item,
// but never let this node fail: an error path that can fail is a silent failure.
let title;
try { title = $('Gigs: Build LLM Prompt').item.json.title; } catch (e) { title = undefined; }
return { json: { problem: 'LLM call failed', title, error: $json.error } };
